  1→#!/usr/bin/env tsx
  2→/**
  3→ * Manual split pipeline for bundled-subject PDFs when kakomon-collector (pdf-lib) cannot split.
  4→ *
  5→ * - Download source PDF (official URL)
  6→ * - Split by explicit page ranges using qpdf
  7→ * - Upload each split PDF to R2
  8→ * - Upsert kakomon_documents rows (is_bundled_origin=true, original_url=source)
  9→ *
 10→ * Usage:
 11→ *   bash -lc 'set -a; source .env; set +a; npx -s tsx scripts/manual-split-upload.ts --plan path/to/manual-split-plan.json --dry-run'
 12→ *   bash -lc 'set -a; source .env; set +a; npx -s tsx scripts/manual-split-upload.ts --plan path/to/manual-split-plan.json --force'
 13→ */
 14→
 15→import { readFileSync, writeFileSync, mkdtempSync, rmSync } from "fs";
 16→import { tmpdir } from "os";
 17→import path from "path";
 18→import { spawnSync } from "child_process";
 19→import crypto from "crypto";
 20→import net from "net";
 21→import { createClient } from "@supabase/supabase-js";
 22→import { uploadToR2 } from "../src/lib/r2";
 23→import { normalizeSubject } from "../src/lib/normalize-subject";
 24→
 25→type PlanOut = {
 26→  r2_path: string;
 27→  // 1-based page range for qpdf, e.g. "1-3" or "7-8"
 28→  pages: string;
 29→  subject_id: string;
 30→  subject_variant?: string | null;
 31→  subject_raw: string;
 32→  subject_display: string;
 33→  exam_type: string;
 34→  exam_type_raw: string;
 35→  exam_variant?: string | null;
 36→  content_type: "problem" | "answer";
 37→};
 38→
 39→type PlanItem = {
 40→  source_url: string;
 41→  university_id: string;
 42→  year: number;
 43→  outputs: PlanOut[];
 44→};
 45→
 46→type PlanFile = {
 47→  generated_at: string;
 48→  items: PlanItem[];
 49→};
 50→
 51→type SummaryItem = {
 52→  r2_path: string;
 53→  subject_id: string;
 54→  pages: string;
 55→  source_url: string;
 56→  bytes?: number;
 57→};
 58→
 59→function getArg(name: string): string | null {
 60→  const idx = process.argv.indexOf(name);
 61→  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
 62→  return null;
 63→}
 64→
 65→function isPrivateOrLocalhost(hostname: string): boolean {
 66→  const h = hostname.toLowerCase();
 67→  if (h === "localhost" || h.endsWith(".localhost") || h.endsWith(".local")) return true;
 68→
 69→  // IP literal checks (best-effort). This does not resolve DNS.
 70→  const ipType = net.isIP(h);
 71→  if (ipType === 4) {
 72→    const parts = h.split(".").map((x) => parseInt(x, 10));
 73→    if (parts.length !== 4 || parts.some((n) => Number.isNaN(n))) return true;
 74→    const [a, b] = parts;
 75→    if (a === 0 || a === 127) return true;
 76→    if (a === 10) return true;
 77→    if (a === 172 && b >= 16 && b <= 31) return true;
 78→    if (a === 192 && b === 168) return true;
 79→    if (a === 169 && b === 254) return true; // link-local
 80→    return false;
 81→  }
 82→  if (ipType === 6) {
 83→    if (h === "::1") return true;
 84→    if (h.startsWith("fe80:")) return true; // link-local
 85→    if (h.startsWith("fc") || h.startsWith("fd")) return true; // unique local
 86→    return false;
 87→  }
 88→  return false;
 89→}
 90→
 91→function validateHttpUrl(input: string): URL {
 92→  let u: URL;
 93→  try {
 94→    u = new URL(input);
 95→  } catch {
 96→    throw new Error(`Invalid URL: ${input}`);
 97→  }
 98→  if (u.protocol !== "https:" && u.protocol !== "http:") {
 99→    throw new Error(`URL must be http(s): ${input}`);
100→  }
101→  if (u.username || u.password) {
102→    throw new Error(`URL must not include credentials: ${input}`);
103→  }
104→  if (isPrivateOrLocalhost(u.hostname)) {
105→    throw new Error(`Refusing localhost/private host URL: ${input}`);
106→  }
107→  return u;
108→}
109→
110→function generateExpectedR2Path(params: {
111→  university_id: string;
112→  year: number;
113→  subject_id: string;
114→  subject_variant?: string | null;
115→  exam_type: string;
116→  exam_variant: string | null | undefined;
117→  content_type: "problem" | "answer";
118→}): string {
119→  const examPart = params.exam_variant ? `${params.exam_type}_${params.exam_variant}` : params.exam_type;
120→  const subjectPart = params.subject_variant ? `${params.subject_id}_${params.subject_variant}` : params.subject_id;
121→  return `${params.university_id}/${params.year}/${subjectPart}/${examPart}/${params.content_type}.pdf`;
122→}
123→
124→function sh(cmd: string, args: string[]) {
125→  const r = spawnSync(cmd, args, { encoding: "utf8", maxBuffer: 50 * 1024 * 1024 });
126→  // qpdf exits 3 for warnings (e.g. object count mismatch) — treat as success
127→  if (r.status !== 0 && !(cmd === "qpdf" && r.status === 3)) {
128→    const msg = (r.stderr || r.stdout || "").trim();
129→    throw new Error(`${cmd} failed: ${cmd} ${args.join(" ")}\n${msg}`);
130→  }
131→  return r.stdout;
132→}
133→
134→function sha8(s: string): string {
135→  return crypto.createHash("sha256").update(s).digest("hex").slice(0, 8);
136→}
137→
138→async function main() {
139→  const planPath = getArg("--plan");
140→  if (!planPath) {
141→    console.error("Error: --plan is required");
142→    process.exit(1);
143→  }
144→  const dryRun = process.argv.includes("--dry-run");
145→  const force = process.argv.includes("--force");
146→  if (!dryRun && !force) {
147→    console.error("Refusing to run LIVE without --force (use --dry-run first)");
148→    process.exit(1);
149→  }
150→
151→  const sbUrl = process.env.SUPABASE_URL;
152→  const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
153→  if (!sbUrl || !sbKey) {
154→    console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
155→    process.exit(1);
156→  }
157→  const supabase = createClient(sbUrl, sbKey);
158→
159→  const plan = JSON.parse(readFileSync(planPath, "utf8")) as PlanFile;
160→  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE"}`);
161→  console.log(`Plan: ${planPath}`);
162→  console.log(`Items: ${plan.items.length}`);
163→
164→  const workDir = mkdtempSync(path.join(tmpdir(), "kakomon-manual-split-"));
165→  console.log(`Workdir: ${workDir}`);
166→
167→  const summary: SummaryItem[] = [];
168→  try {
169→    for (const item of plan.items) {
170→      validateHttpUrl(item.source_url);
171→      const srcPdf = path.join(workDir, `src-${sha8(item.source_url)}.pdf`);
172→      console.log(`\n[download] ${item.source_url}`);
173→      if (!dryRun) {
174→        sh("curl", [
175→          "-L",
176→          "--fail",
177→          "-sS",
178→          "-A",
179→          "Mozilla/5.0",
180→          "--max-redirs",
181→          "5",
182→          "--proto",
183→          "=https,http",
184→          "--proto-redir",
185→          "=https,http",
186→          "-o",
187→          srcPdf,
188→          "--",
189→          item.source_url,
190→        ]);
191→      }
192→
193→      for (const out of item.outputs) {
194→        const expectedKey = generateExpectedR2Path({
195→          university_id: item.university_id,
196→          year: item.year,
197→          subject_id: out.subject_id,
198→          subject_variant: out.subject_variant ?? null,
199→          exam_type: out.exam_type,
200→          exam_variant: out.exam_variant ?? null,
201→          content_type: out.content_type,
202→        });
203→        if (out.r2_path !== expectedKey) {
204→          throw new Error(`Unexpected r2_path (refusing to overwrite arbitrary key)\n  got: ${out.r2_path}\n  expected: ${expectedKey}`);
205→        }
206→
207→        const outPdf = path.join(workDir, `out-${sha8(out.r2_path)}.pdf`);
208→        console.log(`[split] ${out.r2_path} pages=${out.pages}`);
209→        if (!dryRun) {
210→          sh("qpdf", [srcPdf, "--pages", ".", out.pages, "--", outPdf]);
211→        }
212→
213→        if (dryRun) {
214→          summary.push({
215→            r2_path: out.r2_path,
216→            subject_id: out.subject_id,
217→            pages: out.pages,
218→            source_url: item.source_url,
219→          });
220→          continue;
221→        }
222→
223→        const body = readFileSync(outPdf);
224→        await uploadToR2(out.r2_path, body, "application/pdf");
225→
226→        const { error } = await supabase
227→          .from("kakomon_documents")
228→          .upsert(
229→            {
230→              university_id: item.university_id,
231→              year: item.year,
232→              subject: normalizeSubject(out.subject_id),
233→              subject_variant: out.subject_variant ?? null,
234→              subject_raw: out.subject_raw,
235→              subject_display: out.subject_display,
236→              exam_type: out.exam_type,
237→              exam_type_raw: out.exam_type_raw,
238→              content_type: out.content_type,
239→              pdf_storage_path: out.r2_path,
240→              original_url: item.source_url,
241→              is_bundled_origin: true,
242→              updated_at: new Date().toISOString(),
243→            },
244→            { onConflict: "pdf_storage_path" },
245→          );
246→        if (error) throw new Error(`DB upsert failed (${out.r2_path}): ${error.message}`);
247→
248→        summary.push({
249→          r2_path: out.r2_path,
250→          bytes: body.length,
251→          subject_id: out.subject_id,
252→          pages: out.pages,
253→          source_url: item.source_url,
254→        });
255→      }
256→    }
257→  } finally {
258→    // Keep artifacts if dry-run; otherwise cleanup.
259→    if (!dryRun) rmSync(workDir, { recursive: true, force: true });
260→  }
261→
262→  const outSummary = path.resolve(process.cwd(), "manual-split-upload-summary.json");
263→  writeFileSync(outSummary, JSON.stringify({ generated_at: new Date().toISOString(), summary }, null, 2));
264→  console.log(`\nWrote: ${outSummary} (rows=${summary.length})`);
265→}
266→
267→main().catch((err) => {
268→  console.error(err);
269→  process.exit(1);
270→});
271→

  1→#!/usr/bin/env tsx
  2→/**
  3→ * Register DB rows for split outputs (when split PDFs exist in R2 but DB rows are missing).
  4→ *
  5→ * Input expects a "split fixes" JSON file (array) containing entries like:
  6→ * - { action:"split", url, university_id, year, exam_type, exam_variant, exam_type_raw, content_type, bundled_subjects:[...] }
  7→ *
  8→ * Usage:
  9→ *   npx -s tsx scripts/register-split-db.ts --split-fixes path/to/fixes-split.json --dry-run
 10→ *   npx -s tsx scripts/register-split-db.ts --split-fixes path/to/fixes-split.json --force
 11→ *
 12→ * Optional:
 13→ *   --subject-labels path/to/subject-labels.json
 14→ *     JSON shape: { "physics": {"raw":"物理","display":"物理"}, ... }
 15→ */
 16→
 17→import { readFileSync } from "fs";
 18→import { createClient } from "@supabase/supabase-js";
 19→import { resolveSubjectKey } from "../src/lib/r2";
 20→import { normalizeSubject } from "../src/lib/normalize-subject";
 21→
 22→type FixEntry = {
 23→  url?: string;
 24→  university_id: string;
 25→  year: number;
 26→  exam_type: string;
 27→  exam_variant: string | null;
 28→  exam_type_raw?: string | null;
 29→  content_type: "problem" | "answer";
 30→  bundled_subjects: string[] | null;
 31→  action: "split";
 32→  // Optional: if you ever split into variants, this will be used.
 33→  subject_variant?: string | null;
 34→};
 35→
 36→function getArg(name: string): string | null {
 37→  const idx = process.argv.indexOf(name);
 38→  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
 39→  return null;
 40→}
 41→
 42→function mustGetEnv(name: string): string {
 43→  const v = process.env[name];
 44→  if (!v) throw new Error(`${name} is required`);
 45→  return v;
 46→}
 47→
 48→function generateR2Path(params: {
 49→  university_id: string;
 50→  year: number;
 51→  subject_id: string;
 52→  subject_variant: string | null;
 53→  exam_type: string;
 54→  exam_variant: string | null;
 55→  content_type: string;
 56→}): string {
 57→  const subjectPart = params.subject_variant
 58→    ? `${params.subject_id}_${params.subject_variant}`
 59→    : params.subject_id;
 60→  const examPart = params.exam_variant
 61→    ? `${params.exam_type}_${params.exam_variant}`
 62→    : params.exam_type;
 63→  return `${params.university_id}/${params.year}/${subjectPart}/${examPart}/${params.content_type}.pdf`;
 64→}
 65→
 66→function parseEntries(jsonPath: string): FixEntry[] {
 67→  const raw = JSON.parse(readFileSync(jsonPath, "utf8")) as unknown;
 68→  const arr = Array.isArray(raw)
 69→    ? raw
 70→    : (raw as any)?.entries ?? (raw as any)?.items ?? (raw as any)?.fixes;
 71→  if (!Array.isArray(arr)) {
 72→    throw new Error(`Invalid JSON shape: expected array (or {entries/items/fixes: array}): ${jsonPath}`);
 73→  }
 74→  const split = (arr as any[]).filter((e) => e?.action === "split");
 75→  return split as FixEntry[];
 76→}
 77→
 78→function readSubjectLabels(path: string | null): Record<string, { raw: string; display: string }> {
 79→  const defaults: Record<string, { raw: string; display: string }> = {
 80→    math: { raw: "数学", display: "数学" },
 81→    physics: { raw: "物理", display: "物理" },
 82→    chemistry: { raw: "化学", display: "化学" },
 83→    biology: { raw: "生物", display: "生物" },
 84→    earth_science: { raw: "地学", display: "地学" },
 85→    english: { raw: "英語", display: "英語" },
 86→    japanese_lang: { raw: "国語", display: "国語" },
 87→    essay: { raw: "小論文", display: "小論文" },
 88→    general: { raw: "総合問題", display: "総合問題" },
 89→    world_history: { raw: "世界史", display: "世界史" },
 90→    japanese_history: { raw: "日本史", display: "日本史" },
 91→    geography: { raw: "地理", display: "地理" },
 92→    civics: { raw: "公民", display: "公民" },
 93→    info: { raw: "情報", display: "情報" },
 94→  };
 95→  if (!path) return defaults;
 96→
 97→  const parsed = JSON.parse(readFileSync(path, "utf8")) as any;
 98→  const out: Record<string, { raw: string; display: string }> = { ...defaults };
 99→  for (const [k, v] of Object.entries(parsed ?? {})) {
100→    if (v && typeof (v as any).raw === "string" && typeof (v as any).display === "string") {
101→      out[k] = { raw: (v as any).raw, display: (v as any).display };
102→    }
103→  }
104→  return out;
105→}
106→
107→async function main() {
108→  const splitFixesPath = getArg("--split-fixes");
109→  if (!splitFixesPath) {
110→    console.error("Error: --split-fixes is required");
111→    process.exit(1);
112→  }
113→
114→  const dryRun = process.argv.includes("--dry-run");
115→  const force = process.argv.includes("--force");
116→  if (!dryRun && !force) {
117→    console.error("Refusing to run LIVE without --force (use --dry-run first)");
118→    process.exit(1);
119→  }
120→
121→  const labelsPath = getArg("--subject-labels");
122→  const SUBJECT_LABELS = readSubjectLabels(labelsPath);
123→
124→  const url = mustGetEnv("SUPABASE_URL");
125→  const key = mustGetEnv("SUPABASE_SERVICE_ROLE_KEY");
126→  const supabase = createClient(url, key);
127→
128→  const splitEntries = parseEntries(splitFixesPath);
129→  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE"}`);
130→  console.log(`Split entries: ${splitEntries.length}`);
131→
132→  let planned = 0;
133→  const rowsToUpsert: any[] = [];
134→  for (const e of splitEntries) {
135→    if (!e.university_id || !e.year || !e.exam_type || !e.content_type) {
136→      throw new Error(`split entry missing required fields: ${JSON.stringify(e)}`);
137→    }
138→    if (!e.bundled_subjects || e.bundled_subjects.length === 0) {
139→      throw new Error(`bundled_subjects missing/empty for split entry: ${JSON.stringify(e)}`);
140→    }
141→    for (const sid of e.bundled_subjects) {
142→      const sidStr = String(sid);
143→      let subjectKey = sidStr;
144→      try {
145→        subjectKey = resolveSubjectKey(sidStr);
146→      } catch {
147→        // Keep as-is if unknown; this script is for backfilling and may see unexpected subject keys.
148→        subjectKey = sidStr;
149→      }
150→      const lbl = SUBJECT_LABELS[subjectKey] ?? SUBJECT_LABELS[sidStr] ?? { raw: sidStr, display: sidStr };
151→      const r2Path = generateR2Path({
152→        university_id: e.university_id,
153→        year: e.year,
154→        subject_id: subjectKey,
155→        subject_variant: e.subject_variant ?? null,
156→        exam_type: e.exam_type,
157→        exam_variant: e.exam_variant ?? null,
158→        content_type: e.content_type,
159→      });
160→      planned++;
161→
162→      const row = {
163→        university_id: e.university_id,
164→        year: e.year,
165→        subject: normalizeSubject(subjectKey),
166→        subject_variant: e.subject_variant ?? null,
167→        subject_raw: lbl.raw,
168→        subject_display: lbl.display,
169→        exam_type: e.exam_type,
170→        exam_type_raw: e.exam_type_raw ?? "不明",
171→        content_type: e.content_type,
172→        pdf_storage_path: r2Path,
173→        original_url: e.url ?? null,
174→        is_bundled_origin: true,
175→        updated_at: new Date().toISOString(),
176→      };
177→
178→      if (dryRun) {
179→        console.log(`- upsert ${r2Path} subject=${subjectKey} (${lbl.raw}) from ${e.url ?? "(no url)"}`);
180→        continue;
181→      }
182→
183→      rowsToUpsert.push(row);
184→    }
185→  }
186→
187→  if (!dryRun && rowsToUpsert.length > 0) {
188→    // Batch upsert for performance (avoid per-row network calls).
189→    const chunkSize = 500;
190→    for (let i = 0; i < rowsToUpsert.length; i += chunkSize) {
191→      const chunk = rowsToUpsert.slice(i, i + chunkSize);
192→      // eslint-disable-next-line no-await-in-loop
193→      const { error } = await supabase
194→        .from("kakomon_documents")
195→        .upsert(chunk, { onConflict: "pdf_storage_path" });
196→      if (error) throw new Error(`upsert failed (batch starting at ${i}): ${error.message}`);
197→      console.log(`Upserted ${Math.min(i + chunk.length, rowsToUpsert.length)}/${rowsToUpsert.length}`);
198→    }
199→  }
200→
201→  console.log(`Planned split-output DB rows: ${planned}`);
202→}
203→
204→main().catch((err) => {
205→  console.error(err);
206→  process.exit(1);
207→});
