 1→#!/usr/bin/env tsx
 2→/**
 3→ * Ingest local PDF files to R2 + DB.
 4→ * For password-protected PDFs that have been pre-decrypted.
 5→ *
 6→ * Usage:
 7→ *   npx tsx scripts/ingest-local-pdfs.ts --fixes path/to/fixes-add.json --local-dir path/to/decrypted/ --dry-run
 8→ *   npx tsx scripts/ingest-local-pdfs.ts --fixes path/to/fixes-add.json --local-dir path/to/decrypted/ --force
 9→ */
10→
11→import { readFileSync } from "fs";
12→import { createClient } from "@supabase/supabase-js";
13→import { uploadToR2 } from "../src/lib/r2";
14→
15→type FixEntry = {
16→  university_id: string;
17→  year: number;
18→  subject_id: string;
19→  subject_variant: string | null;
20→  subject_raw: string;
21→  subject_display: string;
22→  exam_type: string;
23→  exam_variant: string | null;
24→  exam_type_raw: string;
25→  content_type: "problem" | "answer";
26→  r2_path: string;
27→  local_file: string; // filename in --local-dir
28→};
29→
30→function getArg(name: string): string | null {
31→  const idx = process.argv.indexOf(name);
32→  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
33→  return null;
34→}
35→
36→async function main() {
37→  const fixesPath = getArg("--fixes");
38→  const localDir = getArg("--local-dir");
39→  const dryRun = !process.argv.includes("--force");
40→
41→  if (!fixesPath || !localDir) {
42→    console.error("Usage: --fixes <path> --local-dir <path> [--dry-run | --force]");
43→    process.exit(1);
44→  }
45→
46→  const sbUrl = process.env.SUPABASE_URL;
47→  const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
48→  if (!sbUrl || !sbKey) {
49→    console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
50→    process.exit(1);
51→  }
52→  const supabase = createClient(sbUrl, sbKey);
53→
54→  const entries: FixEntry[] = JSON.parse(readFileSync(fixesPath, "utf8"));
55→  console.log(`Entries: ${entries.length}`);
56→
57→  let done = 0;
58→  for (const e of entries) {
59→    done += 1;
60→    console.log(`\n[${done}/${entries.length}] ${e.r2_path}`);
61→    if (dryRun) continue;
62→
63→    const filePath = `${localDir}/${e.local_file}`;
64→    const body = readFileSync(filePath);
65→    await uploadToR2(e.r2_path, body, "application/pdf");
66→
67→    const { error } = await supabase
68→      .from("kakomon_documents")
69→      .upsert(
70→        {
71→          university_id: e.university_id,
72→          year: e.year,
73→          subject: e.subject_id,
74→          subject_raw: e.subject_raw,
75→          subject_display: e.subject_display,
76→          exam_type: e.exam_type,
77→          exam_type_raw: e.exam_type_raw,
78→          content_type: e.content_type,
79→          pdf_storage_path: e.r2_path,
80→          original_url: `cybercollege://${e.university_id}/${e.year}/${e.local_file}`,
81→          is_bundled_origin: false,
82→          updated_at: new Date().toISOString(),
83→        },
84→        { onConflict: "pdf_storage_path" },
85→      );
86→    if (error) throw new Error(`DB upsert failed (${e.r2_path}): ${error.message}`);
87→  }
88→}
89→
90→main().catch((err) => {
91→  console.error(err);
92→  process.exit(1);
93→});
