114→// ── Supabase ────────────────────────────────────────────────────────────────
115→
116→const sbUrl = process.env.SUPABASE_URL;
117→const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
118→if (!sbUrl || !sbKey) {
119→  console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
120→  process.exit(1);
121→}
122→const supabase = createClient(sbUrl, sbKey);
123→
124→// ── Types ───────────────────────────────────────────────────────────────────
125→
126→interface DocRow {
127→  id: string;
128→  year: number;
129→  subject: string;
130→  exam_type: string;
131→  content_type: string;
132→  pdf_storage_path: string;
133→}
134→
135→type Classification = "E" | "D" | "F" | "ok";
136→
137→interface ComboResult {
138→  university: string;
139→  subject: string;
140→  classification: Classification;
141→  enCount: number;
142→  jaCount: number;
143→  duplicateCount: number;
144→  scienceCount: number;
145→  scienceYears: number[];
146→  missingYears: number[]; // years with science but no individual subject record
147→  deleteTargetIds: string[];
148→  deleteQuestionCount: number;
149→  jaOnlyIds: string[]; // classification F: JA-only records to UPDATE to EN
150→  details: string;
151→}
152→
153→// ── DB helpers ──────────────────────────────────────────────────────────────
154→
155→async function fetchDocs(
156→  universityId: string,
157→  subjectValues: string[],
158→): Promise<DocRow[]> {
159→  const pageSize = 1000;
160→  let from = 0;
161→  const out: DocRow[] = [];
162→  for (;;) {
163→    const to = from + pageSize - 1;
164→    const { data, error } = await supabase
165→      .from("kakomon_documents")
166→      .select("id, year, subject, exam_type, content_type, pdf_storage_path")
167→      .eq("university_id", universityId)
168→      .in("subject", subjectValues)
169→      .order("year", { ascending: true })
170→      .range(from, to);
171→    if (error) throw new Error(`DB select failed for ${universityId}: ${error.message}`);
172→    out.push(...((data as DocRow[]) ?? []));
173→    if (!data || data.length < pageSize) break;
174→    from += pageSize;
175→  }
176→  return out;
177→}
178→
179→async function countQuestions(documentIds: string[]): Promise<number> {
180→  if (documentIds.length === 0) return 0;
181→  let total = 0;
182→  // chunk to avoid URL length issues
183→  const chunkSize = 100;
184→  for (let i = 0; i < documentIds.length; i += chunkSize) {
185→    const chunk = documentIds.slice(i, i + chunkSize);
186→    const { count, error } = await supabase
187→      .from("kakomon_questions")
188→      .select("id", { count: "exact", head: true })
189→      .in("document_id", chunk);
190→    if (error) throw new Error(`count questions failed: ${error.message}`);
191→    total += count ?? 0;
192→  }
193→  return total;
194→}
195→
196→async function deleteDocumentsWithQuestions(docIds: string[]): Promise<{ qDeleted: number; dDeleted: number }> {
197→  if (docIds.length === 0) return { qDeleted: 0, dDeleted: 0 };
198→
199→  const chunkSize = 100;
200→  let qDeleted = 0;
201→  let dDeleted = 0;
202→
203→  for (let i = 0; i < docIds.length; i += chunkSize) {
204→    const chunk = docIds.slice(i, i + chunkSize);
205→
206→    // Delete questions first (FK)
207→    const { data: qData, error: qErr } = await supabase
208→      .from("kakomon_questions")
209→      .delete()
210→      .in("document_id", chunk)
211→      .select("id");
212→    if (qErr) throw new Error(`delete questions failed: ${qErr.message}`);
213→    qDeleted += qData?.length ?? 0;
214→
215→    // Delete documents
216→    const { data: dData, error: dErr } = await supabase
217→      .from("kakomon_documents")
218→      .delete()
219→      .in("id", chunk)
220→      .select("id");
221→    if (dErr) throw new Error(`delete documents failed: ${dErr.message}`);
222→    dDeleted += dData?.length ?? 0;
223→  }
224→
225→  return { qDeleted, dDeleted };
226→}
227→
228→// ── Analysis ────────────────────────────────────────────────────────────────
229→
230→async function analyzeCombo(university: string, subject: string): Promise<ComboResult> {
231→  const enKey = subject;
232→  const jaKey = SUBJECT_MAP[subject];
233→  if (!jaKey) throw new Error(`No JA mapping for subject: ${subject}`);
234→
235→  // Fetch EN and JA records
236→  const enDocs = await fetchDocs(university, [enKey]);
237→  const jaDocs = await fetchDocs(university, [jaKey]);
238→
239→  // JA/EN duplicate detection
240→  const makeKey = (r: DocRow) => `${r.year}|${r.exam_type}|${r.content_type}`;
241→  const enKeySet = new Set(enDocs.map(makeKey));
242→  const jaKeySet = new Set(jaDocs.map(makeKey));
243→  const duplicateKeys = [...enKeySet].filter((k) => jaKeySet.has(k));
244→
245→  // Build delete targets: JA-side records that overlap with EN
246→  const duplicateKeySet = new Set(duplicateKeys);
247→  const jaDeleteTargets = jaDocs.filter((r) => duplicateKeySet.has(makeKey(r)));
248→  const jaDeleteIds = jaDeleteTargets.map((r) => r.id);
249→
250→  // Classification F: JA-only records (no EN counterpart) → UPDATE subject to EN
251→  const jaOnlyDocs = jaDocs.filter((r) => !duplicateKeySet.has(makeKey(r)));
252→  const jaOnlyIds = jaOnlyDocs.map((r) => r.id);
253→
254→  // Count questions on those JA records
255→  const qCount = jaDeleteIds.length > 0 ? await countQuestions(jaDeleteIds) : 0;
256→
257→  // Science bundle detection (chemistry, physics, biology, earth_science)
258→  let scienceDocs: DocRow[] = [];
259→  let missingYears: number[] = [];
260→  if (SCIENCE_SUBJECTS.includes(subject)) {
261→    scienceDocs = await fetchDocs(university, SCIENCE_KEYS);
262→    if (scienceDocs.length > 0) {
263→      // Find years where science exists but individual subject doesn't
264→      const scienceYearSet = new Set(scienceDocs.map((r) => r.year));
265→      const enYearSet = new Set(enDocs.map((r) => r.year));
266→      const jaYearSet = new Set(jaDocs.map((r) => r.year));
267→      missingYears = [...scienceYearSet].filter(
268→        (y) => !enYearSet.has(y) && !jaYearSet.has(y),
269→      ).sort();
270→    }
271→  }
272→
273→  // Classify (E > F > D > ok)
274→  let classification: Classification = "ok";
275→  let details: string;
276→
277→  if (duplicateKeys.length > 0) {
278→    classification = "E";
279→    details = [
280→      `EN: ${enDocs.length}件 (subject=${enKey})`,
281→      `JA: ${jaDocs.length}件 (subject=${jaKey})`,
282→      `重複ペア: ${duplicateKeys.length}件 (同一 year/exam_type/content_type)`,
283→      `→ 削除対象: JA側 ${jaDeleteIds.length}レコード (questions: ${qCount}件)`,
284→      ...(jaOnlyIds.length > 0 ? [`→ JA-only (F): ${jaOnlyIds.length}レコード → EN UPDATE対象`] : []),
285→    ].join("\n  ");
286→  } else if (jaOnlyIds.length > 0) {
287→    classification = "F";
288→    details = [
289→      `EN: ${enDocs.length}件 (subject=${enKey})`,
290→      `JA-only: ${jaOnlyIds.length}件 (subject=${jaKey}, EN側なし)`,
291→      `→ UPDATE対象: subject "${jaKey}" → "${enKey}"`,
292→    ].join("\n  ");
293→  } else if (scienceDocs.length > 0 && missingYears.length > 0) {
294→    classification = "D";
295→    const scienceYears = [...new Set(scienceDocs.map((r) => r.year))].sort();
296→    details = [
297→      `理科/science レコード: ${scienceDocs.length}件 (${scienceYears.join(",")})`,
298→      `${enKey} 個別レコード: ${enDocs.length + jaDocs.length}件`,
299→      `要確認年: ${missingYears.join(", ")}`,
300→    ].join("\n  ");
301→  } else {
302→    details = `EN ${enDocs.length}件, JA ${jaDocs.length}件`;
303→  }
304→
305→  return {
306→    university,
307→    subject,
308→    classification,
309→    enCount: enDocs.length,
310→    jaCount: jaDocs.length,
311→    duplicateCount: duplicateKeys.length,
312→    scienceCount: scienceDocs.length,
313→    scienceYears: [...new Set(scienceDocs.map((r) => r.year))].sort(),
314→    missingYears,
315→    deleteTargetIds: jaDeleteIds,
316→    deleteQuestionCount: qCount,
317→    jaOnlyIds,
318→    details,
319→  };
320→}
321→
322→// ── Main ────────────────────────────────────────────────────────────────────
323→
324→async function main() {
325→  // Filter combos
326→  let combos = ALL_COMBOS;
327→  if (filterUnis) {
328→    combos = combos.filter((c) => filterUnis.includes(c.university));
329→  }
330→  if (filterSubjects) {
331→    combos = combos.filter((c) => filterSubjects.includes(c.subject));
332→  }
333→
334→  console.log(`=== JA/EN 再監査レポート ===`);
335→  console.log(`対象: ${combos.length}コンボ  mode: ${isFix ? (isForce ? "FIX (LIVE)" : "FIX (dry-run)") : "REPORT"}\n`);
336→
337→  const results: ComboResult[] = [];
338→  for (const combo of combos) {
339→    const r = await analyzeCombo(combo.university, combo.subject);
340→    results.push(r);
341→
342→    // Print each result immediately
343→    const label = `${r.university} × ${r.subject}`;
344→    if (r.classification === "E") {
345→      console.log(`[E] ${label}: JA/EN重複 ${r.duplicateCount}件`);
346→    } else if (r.classification === "F") {
347→      console.log(`[F] ${label}: JA-only ${r.jaOnlyIds.length}件 → EN UPDATE`);
348→    } else if (r.classification === "D") {
349→      console.log(`[D] ${label}: 理科バンドル発見`);
350→    } else {
351→      console.log(`[ok] ${label}: Clean`);
352→    }
353→    console.log(`  ${r.details}\n`);
354→  }
355→
356→  // Summary
357→  const eResults = results.filter((r) => r.classification === "E");
358→  const fResults = results.filter((r) => r.classification === "F");
359→  const dResults = results.filter((r) => r.classification === "D");
360→  const okResults = results.filter((r) => r.classification === "ok");
361→  const totalDeleteDocs = eResults.reduce((s, r) => s + r.deleteTargetIds.length, 0);
362→  const totalDeleteQ = eResults.reduce((s, r) => s + r.deleteQuestionCount, 0);
363→  const totalJaOnly = [...eResults, ...fResults].reduce((s, r) => s + r.jaOnlyIds.length, 0);
364→
365→  console.log(`=== サマリー ===`);
366→  console.log(`全${results.length}コンボ中:`);
367→  console.log(`  分類E (JA/EN重複): ${eResults.length}件 (削除対象docs: ${totalDeleteDocs}, questions: ${totalDeleteQ}) → --fix で削除可能`);
368→  console.log(`  分類F (JA-only→EN): ${fResults.length}件 (UPDATE対象: ${totalJaOnly}レコード) → --fix でUPDATE可能`);
369→  console.log(`  分類D (理科バンドル): ${dResults.length}件 → 手動確認必要`);
370→  console.log(`  Clean: ${okResults.length}件`);
371→
372→  // Fix mode
373→  const fixableE = eResults.filter((r) => r.deleteTargetIds.length > 0);
374→  const fixableF = [...eResults, ...fResults].filter((r) => r.jaOnlyIds.length > 0);
375→
376→  if (isFix && (fixableE.length > 0 || fixableF.length > 0)) {
377→    console.log(`\n=== 修正 (${isForce ? "LIVE" : "dry-run"}) ===`);
378→
379→    // Fix E: delete JA duplicates
380→    for (const r of fixableE) {
381→      const label = `${r.university} × ${r.subject}`;
382→      if (!isForce) {
383→        console.log(`[E dry-run] ${label}: would delete ${r.deleteTargetIds.length} JA docs + ${r.deleteQuestionCount} questions`);
384→        if (r.deleteTargetIds.length <= 10) {
385→          console.log(`  IDs: ${r.deleteTargetIds.join(", ")}`);
386→        } else {
387→          console.log(`  IDs: ${r.deleteTargetIds.slice(0, 5).join(", ")} ... (${r.deleteTargetIds.length} total)`);
388→        }
389→      } else {
390→        const { qDeleted, dDeleted } = await deleteDocumentsWithQuestions(r.deleteTargetIds);
391→        console.log(`[E DELETED] ${label}: ${dDeleted} docs, ${qDeleted} questions`);
392→      }
393→    }
394→
395→    // Fix F: UPDATE JA-only records to EN subject key
396→    for (const r of fixableF) {
397→      const enKey = r.subject;
398→      const label = `${r.university} × ${r.subject}`;
399→      if (!isForce) {
400→        console.log(`[F dry-run] ${label}: would UPDATE ${r.jaOnlyIds.length} records subject → "${enKey}"`);
401→        if (r.jaOnlyIds.length <= 10) {
402→          console.log(`  IDs: ${r.jaOnlyIds.join(", ")}`);
403→        } else {
404→          console.log(`  IDs: ${r.jaOnlyIds.slice(0, 5).join(", ")} ... (${r.jaOnlyIds.length} total)`);
405→        }
406→      } else {
407→        const chunkSize = 100;
408→        let updated = 0;
409→        for (let i = 0; i < r.jaOnlyIds.length; i += chunkSize) {
410→          const chunk = r.jaOnlyIds.slice(i, i + chunkSize);
411→          const { error } = await supabase
412→            .from("kakomon_documents")
413→            .update({ subject: enKey })
414→            .in("id", chunk);
415→          if (error) throw new Error(`UPDATE failed for ${label}: ${error.message}`);
416→          updated += chunk.length;
417→        }
418→        console.log(`[F UPDATED] ${label}: ${updated} records → subject="${enKey}"`);
419→      }
420→    }
421→  }
422→}
423→
424→main().catch((err) => {
425→  console.error(err);
426→  process.exit(1);
427→});
