 1→import {
 2→  S3Client,
 3→  GetObjectCommand,
 4→  PutObjectCommand,
 5→} from "@aws-sdk/client-s3";
 6→
 7→/** 科目名（日本語）→ ASCIIキーのマッピング */
 8→const SUBJECT_KEY_MAP: Record<string, string> = {
 9→  数学: "math",
10→  物理: "physics",
11→  化学: "chemistry",
12→  生物: "biology",
13→  英語: "english",
14→  国語: "japanese",
15→};
16→
17→/** ASCIIキー → 日本語の逆引きマッピング */
18→const SUBJECT_KEY_REVERSE: Record<string, string> = Object.fromEntries(
19→  Object.entries(SUBJECT_KEY_MAP).map(([ja, en]) => [en, ja]),
20→);
21→
22→/** ASCIIキーの集合（高速ルックアップ用） */
23→const VALID_ASCII_KEYS = new Set(Object.values(SUBJECT_KEY_MAP));
24→
25→/**
26→ * 科目名をASCIIキーに変換する
27→ * 日本語（"物理"）でもASCIIキー（"physics"）でも受け付ける
28→ */
29→export function resolveSubjectKey(subject: string): string {
30→  // 既にASCIIキーならそのまま返す
31→  if (VALID_ASCII_KEYS.has(subject)) return subject;
32→
33→  // 物理DIなどの派生科目キー（例: physics_di）を許容する
34→  if (/^[a-z][a-z0-9_]*$/.test(subject)) return subject;
35→
36→  // 日本語 → ASCIIキー
37→  const key = SUBJECT_KEY_MAP[subject];
38→  if (key) return key;
39→
40→  const validJa = Object.keys(SUBJECT_KEY_MAP).join(", ");
41→  const validEn = Object.values(SUBJECT_KEY_MAP).join(", ");
42→  throw new Error(`Unknown subject: "${subject}" (valid: ${validJa} / ${validEn})`);
43→}
44→
45→/**
46→ * ASCIIキーまたは日本語の科目名を日本語に変換する
47→ */
48→export function resolveSubjectName(subject: string): string {
49→  if (SUBJECT_KEY_REVERSE[subject]) return SUBJECT_KEY_REVERSE[subject];
50→  if (SUBJECT_KEY_MAP[subject]) return subject;
51→  return subject;
52→}
53→
54→let r2Client: S3Client | null = null;
55→
56→function getR2Client(): S3Client {
57→  if (r2Client) return r2Client;
58→
59→  const accountId = process.env.R2_ACCOUNT_ID;
60→  const accessKeyId = process.env.R2_ACCESS_KEY_ID;
61→  const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
62→
63→  if (!accountId || !accessKeyId || !secretAccessKey) {
64→    throw new Error(
65→      "R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY are required",
66→    );
67→  }
68→
69→  r2Client = new S3Client({
70→    region: "auto",
71→    endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
72→    credentials: {
73→      accessKeyId,
74→      secretAccessKey,
75→    },
76→  });
77→
78→  return r2Client;
79→}
