#!/usr/bin/env tsx
/**
 * Ingest local PDF files to R2 + DB.
 * For password-protected PDFs that have been pre-decrypted.
 *
 * Usage:
 *   npx tsx scripts/ingest-local-pdfs.ts --fixes path/to/fixes-add.json --local-dir path/to/decrypted/ --dry-run
 *   npx tsx scripts/ingest-local-pdfs.ts --fixes path/to/fixes-add.json --local-dir path/to/decrypted/ --force
 */

import { readFileSync } from "fs";
import { createClient } from "@supabase/supabase-js";
import { uploadToR2 } from "../src/lib/r2";

type FixEntry = {
  university_id: string;
  year: number;
  subject_id: string;
  subject_variant: string | null;
  subject_raw: string;
  subject_display: string;
  exam_type: string;
  exam_variant: string | null;
  exam_type_raw: string;
  content_type: "problem" | "answer";
  r2_path: string;
  local_file: string; // filename in --local-dir
};

function getArg(name: string): string | null {
  const idx = process.argv.indexOf(name);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return null;
}

async function main() {
  const fixesPath = getArg("--fixes");
  const localDir = getArg("--local-dir");
  const dryRun = !process.argv.includes("--force");

  if (!fixesPath || !localDir) {
    console.error("Usage: --fixes <path> --local-dir <path> [--dry-run | --force]");
    process.exit(1);
  }

  const sbUrl = process.env.SUPABASE_URL;
  const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!sbUrl || !sbKey) {
    console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
    process.exit(1);
  }
  const supabase = createClient(sbUrl, sbKey);

  const entries: FixEntry[] = JSON.parse(readFileSync(fixesPath, "utf8"));
  console.log(`Entries: ${entries.length}`);

  let done = 0;
  for (const e of entries) {
    done += 1;
    console.log(`\n[${done}/${entries.length}] ${e.r2_path}`);
    if (dryRun) continue;

    const filePath = `${localDir}/${e.local_file}`;
    const body = readFileSync(filePath);
    await uploadToR2(e.r2_path, body, "application/pdf");

    const { error } = await supabase
      .from("kakomon_documents")
      .upsert(
        {
          university_id: e.university_id,
          year: e.year,
          subject: e.subject_id,
          subject_raw: e.subject_raw,
          subject_display: e.subject_display,
          exam_type: e.exam_type,
          exam_type_raw: e.exam_type_raw,
          content_type: e.content_type,
          pdf_storage_path: e.r2_path,
          original_url: `cybercollege://${e.university_id}/${e.year}/${e.local_file}`,
          is_bundled_origin: false,
          updated_at: new Date().toISOString(),
        },
        { onConflict: "pdf_storage_path" },
      );
    if (error) throw new Error(`DB upsert failed (${e.r2_path}): ${error.message}`);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

