/**
 * Subject normalization: ensures subject values are always stored as English keys.
 */

export const SUBJECT_MAP_JA_TO_EN: Record<string, string> = {
  "数学": "math",
  "物理": "physics",
  "化学": "chemistry",
  "生物": "biology",
  "地学": "earth_science",
  "英語": "english",
  "国語": "japanese_lang",
  "小論文": "essay",
  "総合問題": "general",
  "世界史": "world_history",
  "日本史": "japanese_history",
  "地理": "geography",
  "公民": "civics",
  "情報": "info",
  "理科": "science",
};

export const VALID_SUBJECT_KEYS = new Set(Object.values(SUBJECT_MAP_JA_TO_EN));

/**
 * Normalize a subject value to its canonical English key.
 * Throws on unknown values.
 */
export function normalizeSubject(raw: string): string {
  // Already an EN key?
  if (VALID_SUBJECT_KEYS.has(raw)) return raw;
  // JA → EN lookup
  const en = SUBJECT_MAP_JA_TO_EN[raw];
  if (en) return en;
  // Partial match for compound names like "化学基礎・化学" → "chemistry"
  for (const [ja, enVal] of Object.entries(SUBJECT_MAP_JA_TO_EN)) {
    if (raw.includes(ja)) return enVal;
  }
  throw new Error(`Unknown subject: "${raw}" — add to SUBJECT_MAP`);
}

