const plan = { generated_at: new Date().toISOString(), items: [] };

for (const item of items) {
  const cls = JSON.parse(readFileSync(`${DIR}/${item.file}`, "utf8"));

  // Assign subjects to pages using classification + inference
  const pageSubjects = [];
  for (const p of cls.pages) {
    let subject = p.subject;
    if (!subject && p.type !== "cover" && p.type !== "blank") {
      subject = inferSubject(p.note);
    }
    pageSubjects.push({ page: p.page, subject, type: p.type });
  }

  // Group contiguous pages by subject, skipping cover/blank/null
  const groups = [];
  let current = null;
  for (const ps of pageSubjects) {
    if (!ps.subject) {
      // For science problem PDFs, skip non-subject pages (cover, blank)
      // For answer PDFs, also skip null-subject pages
      if (current) {
        groups.push({ ...current });
        current = null;
      }
      continue;
