#!/usr/bin/env node
/**
 * Generate manual-split-plan.json from pdf_splitter.py classification results.
 * For shiga_pref rebuild only.
 */
import { readFileSync, writeFileSync } from "fs";

// Subject inference from note text (for answer PDFs where subject is null)
// IMPORTANT: compound checks (小論文+specific) must come before simple checks (化学)
// because "人間文化学部" contains "化学" as a substring
function inferSubject(note) {
  if (!note) return null;
  const n = note;
  // Essay variants first (before 化学 check, since 人間文化学部 contains 化学)
  if (n.includes("小論文") && n.includes("環境生態")) return "essay_seitai";
  if (n.includes("小論文") && n.includes("環境政策")) return "essay_seisaku";
  if (n.includes("小論文") && n.includes("人間文化")) return "essay_bunkei";
  if (n.includes("小論文")) return "essay";
  // Other compound subjects
  if (n.includes("総合問題")) return "general";
  if (n.includes("造形実技")) return "art";
  if (n.includes("デッサン")) return "drawing";
  // Simple science subjects
  if (n.includes("物理")) return "physics";
  if (n.includes("化学")) return "chemistry";
  if (n.includes("生物")) return "biology";
  if (n.includes("国語")) return "japanese_lang";
  if (n.includes("数学")) return "math";
  if (n.includes("英語")) return "english";
  return null;
}

const SUBJECT_DISPLAY = {
  physics: "物理", chemistry: "化学", biology: "生物",
  math: "数学", english: "英語", japanese_lang: "国語",
  essay: "小論文", essay_seitai: "小論文（環境生態学科）",
  essay_seisaku: "小論文（環境政策・計画学科）", essay_bunkei: "小論文（人間文化学部）",
  general: "総合問題", art: "造形実技", drawing: "デッサン"
};

// Variant info: subject_id → { id, variant }
function subjectParts(sid) {
  if (sid === "essay_seitai") return { id: "essay", variant: "seitai" };
  if (sid === "essay_seisaku") return { id: "essay", variant: "seisaku" };
  if (sid === "essay_bunkei") return { id: "essay", variant: "bunkei" };
  return { id: sid, variant: null };
}

function r2Path(uid, year, sid, variant, examType, contentType) {
  const subjPart = variant ? `${sid}_${variant}` : sid;
  return `${uid}/${year}/${subjPart}/${examType}/${contentType}.pdf`;
}

// Define all bundled PDFs with metadata
const items = [
  // R7 (2025) answers
  { file: "classification_r7_zenki_kaitou.json", url: "https://www.usp.ac.jp/nyushi/items/r7_zenki_kaitou.pdf", year: 2025, examType: "zenki", examTypeRaw: "前期日程", contentType: "answer" },
  { file: "classification_r7_kouki_kaitou.json", url: "https://www.usp.ac.jp/nyushi/items/r7_kouki_kaitou.pdf", year: 2025, examType: "kouki", examTypeRaw: "後期日程", contentType: "answer" },
  // R7 (2025) - no rika (already separate physics/chemistry)

  // R6 (2024) rika + answers
  { file: "classification_2024_zenki_rika.json", url: "https://www.usp.ac.jp/nyushi/items/2024_zenki_rika_1.pdf", year: 2024, examType: "zenki", examTypeRaw: "前期日程", contentType: "problem" },
  { file: "classification_2024_zenki_kohyokaito_1.json", url: "https://www.usp.ac.jp/nyushi/items/2024_zenki_kohyokaito_1.pdf", year: 2024, examType: "zenki", examTypeRaw: "前期日程", contentType: "answer" },
  { file: "classification_2024_koki_rika.json", url: "https://www.usp.ac.jp/nyushi/items/2024_koki_rika.pdf", year: 2024, examType: "kouki", examTypeRaw: "後期日程", contentType: "problem" },
  { file: "classification_2024_koki_kohyokaito.json", url: "https://www.usp.ac.jp/nyushi/items/2024_koki_kohyokaito.pdf", year: 2024, examType: "kouki", examTypeRaw: "後期日程", contentType: "answer" },

  // R5 (2023)
  { file: "classification_r5_zenki_rika.json", url: "https://www.usp.ac.jp/nyushi/items/r5_zenki_rika.pdf", year: 2023, examType: "zenki", examTypeRaw: "前期日程", contentType: "problem" },
  { file: "classification_r5_zenki_answer.json", url: "https://www.usp.ac.jp/nyushi/items/r5_zenki_answer.PDF", year: 2023, examType: "zenki", examTypeRaw: "前期日程", contentType: "answer" },
  { file: "classification_r5_koki_rika.json", url: "https://www.usp.ac.jp/nyushi/items/r5_koki_rika.pdf", year: 2023, examType: "kouki", examTypeRaw: "後期日程", contentType: "problem" },
  { file: "classification_r5_koki_answer.json", url: "https://www.usp.ac.jp/nyushi/items/r5_koki_answer.PDF", year: 2023, examType: "kouki", examTypeRaw: "後期日程", contentType: "answer" },

  // R4 (2022)
  { file: "classification_r4mae_rika.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2022, examType: "zenki", examTypeRaw: "前期日程", contentType: "problem" },
  { file: "classification_r4mae_kaitou.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2022, examType: "zenki", examTypeRaw: "前期日程", contentType: "answer" },
  { file: "classification_r4kouki_rika.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2022, examType: "kouki", examTypeRaw: "後期日程", contentType: "problem" },
  { file: "classification_r4kouki_kaitou.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2022, examType: "kouki", examTypeRaw: "後期日程", contentType: "answer" },

  // R3 (2021)
  { file: "classification_r3mae_rika.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2021, examType: "zenki", examTypeRaw: "前期日程", contentType: "problem" },
  { file: "classification_r3mae_kaitou2.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2021, examType: "zenki", examTypeRaw: "前期日程", contentType: "answer" },
  { file: "classification_r3kouki_rika.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2021, examType: "kouki", examTypeRaw: "後期日程", contentType: "problem" },
  { file: "classification_r3kouki_kaitou2.json", url: "https://www.usp.ac.REDACTED.pdf", year: 2021, examType: "kouki", examTypeRaw: "後期日程", contentType: "answer" },
];

const DIR = "rebuild-shiga_pref-20260226";
const plan = { generated_at: new Date().toISOString(), items: [] };

for (const item of items) {
  const cls = JSON.parse(readFileSync(`${DIR}/${item.file}`, "utf8"));

  // Assign subjects to pages using classification + inference
  const pageSubjects = [];
  for (const p of cls.pages) {
    let subject = p.subject;
    if (!subject && p.type !== "cover" && p.type !== "blank") {
      subject = inferSubject(p.note);
    }
    pageSubjects.push({ page: p.page, subject, type: p.type });
  }

  // Group contiguous pages by subject, skipping cover/blank/null
  const groups = [];
  let current = null;
  for (const ps of pageSubjects) {
    if (!ps.subject) {
      // For science problem PDFs, skip non-subject pages (cover, blank)
      // For answer PDFs, also skip null-subject pages
      if (current) {
        groups.push({ ...current });
        current = null;
      }
      continue;
    }
    if (current && current.subject === ps.subject) {
      current.endPage = ps.page;
    } else {
      if (current) groups.push({ ...current });
      current = { subject: ps.subject, startPage: ps.page, endPage: ps.page };
    }
  }
  if (current) groups.push(current);

  // Merge non-contiguous pages of same subject (sometimes blank pages interrupt)
  const merged = [];
  for (const g of groups) {
    const existing = merged.find(m => m.subject === g.subject);
    if (existing) {
      // Extend range to include gap (blank pages between same subject)
      existing.endPage = g.endPage;
    } else {
      merged.push({ ...g });
    }
  }

  const outputs = merged.map(g => {
    const { id, variant } = subjectParts(g.subject);
    return {
      r2_path: r2Path("shiga_pref", item.year, id, variant, item.examType, item.contentType),
      pages: g.startPage === g.endPage ? `${g.startPage}` : `${g.startPage}-${g.endPage}`,
      subject_id: id,
      subject_variant: variant,
      subject_raw: SUBJECT_DISPLAY[g.subject] || g.subject,
      subject_display: SUBJECT_DISPLAY[g.subject] || g.subject,
      exam_type: item.examType,
      exam_type_raw: item.examTypeRaw,
      content_type: item.contentType,
    };
  });

  plan.items.push({
    source_url: item.url,
    university_id: "shiga_pref",
    year: item.year,
    outputs
  });
}

writeFileSync(`${DIR}/manual-split-plan.json`, JSON.stringify(plan, null, 2));
console.log(`Generated ${plan.items.length} items with ${plan.items.reduce((s, i) => s + i.outputs.length, 0)} total outputs`);

// Duplicate r2_path check
const allPaths = plan.items.flatMap(i => i.outputs.map(o => o.r2_path));
const dupes = allPaths.filter((p, i) => allPaths.indexOf(p) !== i);
if (dupes.length) {
  console.error("DUPLICATE r2_paths:", [...new Set(dupes)]);
  process.exit(1);
} else {
  console.log("No duplicate r2_paths ✓");
}

